const table=(title,rows)=>`<div class="verified-table" tabindex="0" role="region" aria-label="${title}"><table><thead><tr><th>확인 항목</th><th>정리할 내용</th></tr></thead><tbody>${rows.map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table></div>`;
const body=sections=>sections.map(([heading,...paragraphs])=>`<h2>${heading}</h2>${paragraphs.map(p=>p.startsWith('<')?p:`<p>${p}</p>`).join('')}`).join('\n');
const post=(slug,title,category,label,image,check,description,intro,sections,faq,sources,related)=>({slug,title,category,label,image:`/assets/${image}-2026.webp`,check,description,intro,body:body(sections),faq,sources,related,verifiedAt:'2026-10-07'});

module.exports=[
post('자발적-퇴사-실업급여-인정사유-증빙','자발적 퇴사 실업급여 인정 사유와 준비할 증빙','money','실업급여 수급 판단','job-resignation-benefit','퇴사 사유·회피 노력·객관적 자료','자발적으로 퇴사했어도 수급자격이 제한되지 않을 수 있는 사유와 퇴사 전에 준비할 객관적 자료를 정리했습니다.','자발적으로 사직서를 냈다는 사실만으로 실업급여 가능 여부가 결정되지는 않습니다. 퇴사가 불가피했던 사유와 이를 피하려 했던 과정, 실제 자료를 함께 살펴야 합니다.',[
['자발적 퇴사도 예외 사유를 따져봅니다','고용24는 실업급여를 원칙적으로 비자발적 이직자에게 인정하지만, 이직을 피하려 노력했음에도 계속 근무하기 곤란했던 자발적 이직에는 정당한 사유가 인정될 수 있다고 안내합니다. 핵심은 “힘들어서 그만뒀다”는 표현이 아니라 어떤 상황이 언제부터 얼마나 지속됐고 다른 선택이 어려웠는지를 자료로 설명하는 것입니다.','임금체불, 채용 때보다 낮아진 근로조건, 최저임금 미달, 법정 연장근로 제한 위반처럼 공식 안내에 열거된 사유가 있습니다. 질병·부상, 가족 돌봄, 통근 곤란 등은 개인별 사실관계와 요건을 더 확인해야 합니다. 사유 이름만 비슷하다고 자동 인정되는 것은 아닙니다.'],
['퇴사 전에 날짜별로 사실을 정리하세요',table('퇴사 사유 증빙 메모',[['근로조건','근로계약서·급여명세서·근무표의 변경 전후'],['회사 요청','개선 요청 메일·문자와 회사 답변'],['건강·돌봄','공식 진단·상담·휴직 검토 자료'],['통근','사업장 이전일과 실제 이동 경로·시간'],['퇴사 절차','사직서에 적은 사유와 최종 근무일']]),'증빙은 많이 모으는 것보다 퇴사 사유와 직접 연결되는 자료가 중요합니다. 개인 대화를 무단 공개하거나 의료정보를 불필요하게 제출하지 말고, 수급자격 상담에서 요구하는 범위를 확인하세요.'],
['이직회피 노력을 함께 설명하세요','근무시간 조정, 업무 변경, 휴직, 사업장 이동 등 가능한 대안을 회사에 요청했는지가 판단에 영향을 줄 수 있습니다. 실제로 요청하지 못한 특별한 사정이 있다면 그 이유를 정리합니다. 회사와 갈등이 있었다는 사실만으로 이직회피 노력이 입증되는 것은 아닙니다.','구두 요청만 했다면 날짜와 상대방, 요청 내용, 답변을 기억나는 범위에서 정리하세요. 앞으로 퇴사를 준비 중이라면 이메일이나 회사의 공식 채널처럼 나중에 확인할 수 있는 방식이 도움이 됩니다. 사실과 다른 자료를 새로 만들거나 회사의 답변을 왜곡하면 안 됩니다.'],
['사직서와 이직확인서 내용을 대조하세요','사직서에 개인 사정이라고만 적혔더라도 실제 퇴사 경위가 사라지는 것은 아니지만 설명 부담이 커질 수 있습니다. 제출 전 사실에 맞는 표현인지 확인하고 사본을 보관하세요. 회사가 제출한 이직확인서의 이직 사유도 고용24에서 처리 여부와 함께 확인할 수 있습니다.','회사 기재 내용과 실제 사실이 다르면 감정적으로 항의하기보다 근로계약서, 급여내역, 문자 등 차이를 보여주는 자료를 정리해 관할 고용센터에 상담하세요. 회사가 작성한 코드 하나만으로 최종 수급자격이 자동 확정되는 것은 아닙니다.'],
['신청 전에 고용센터에 확인할 질문','내 사유가 정당한 이직사유의 어느 항목과 관련되는지, 추가로 필요한 자료가 무엇인지, 피보험단위기간 등 다른 수급요건은 충족하는지를 질문합니다. 퇴사 사유가 인정돼도 구직 의사와 능력, 가입기간 등 전체 요건을 함께 충족해야 합니다.','온라인 경험담은 비슷해 보여도 근무기간과 증빙이 다릅니다. 이 글은 개인의 수급자격을 판정하지 않습니다. 퇴사 전이라면 자료를 정리한 뒤 고용노동부 고객상담센터 또는 관할 고용센터에서 본인 상황을 구체적으로 확인하세요.'],
['상담 메모는 사실과 질문을 분리합니다','상담 전에 사실, 가지고 있는 자료, 확인할 질문을 세 칸으로 나눠 적어보세요. 예를 들어 “3개월간 임금 일부가 늦게 지급됨”은 사실이고 “정당한 이직사유에 해당하는가”는 질문입니다. 결론을 먼저 정해두고 사실을 끼워 맞추지 않아야 정확한 안내를 받을 수 있습니다.','상담 일시와 안내받은 추가 자료를 적고 실제 신청 화면의 최신 안내와 다시 대조합니다. 전화 상담 내용만으로 수급자격이 확정됐다고 생각하지 말고, 신청 후 담당 기관의 사실 확인과 결정을 기다려야 합니다.']
],[['개인 사정으로 사직서를 썼으면 무조건 받을 수 없나요?','사직서 문구만으로 모든 판단이 끝나지는 않지만 실제 사유를 설명할 자료가 중요합니다. 고용센터에서 사실관계를 확인받으세요.'],['회사와 합의해 퇴사하면 비자발적 퇴사인가요?','합의라는 표현만으로 판단할 수 없습니다. 누가 어떤 이유로 퇴사를 제안했고 실제 선택 여지가 있었는지 확인합니다.'],['퇴사한 뒤 증빙을 준비해도 되나요?','가능한 자료는 준비할 수 있지만 회사 시스템 접근이 끊기기 전에 합법적으로 보관할 자료를 정리하는 편이 좋습니다.']],
[['고용24 자발적 이직자 실업급여 제한 안내','https://ei.work24.go.kr/ei/eim/eg/ei/eiEminsr/retrievePb0201Info.do'],['고용24 실업급여 제도 안내','https://m.work24.go.kr/cm/c/f/1100/selecSystInfo.do?currentPageNo=1&recordCountPerPage=10&systClId=SC00000255&systId=SI00000387']],['실업급여-신청-전-확인할-것','실업급여-아르바이트-소득신고','고용24-구직등록-방법']),

post('이직확인서-처리여부-조회-정정요청','이직확인서 처리여부 조회와 퇴사 사유 정정 방법','money','이직확인서 확인','separation-confirmation','처리 상태·이직 사유·임금 자료','실업급여 신청 전에 이직확인서 처리 상태와 이직 사유를 확인하고 실제 내용과 다를 때 준비할 자료를 안내합니다.','이직확인서는 퇴사 확인서가 아니라 실업급여 수급자격 판단에 쓰이는 자료입니다. 제출 여부만 보지 말고 이직 사유와 임금·근무기간이 실제와 맞는지도 확인하세요.',[
['이직확인서에는 수급 판단 자료가 담깁니다','고용24는 이직확인서를 이직 사유, 이직일, 평균임금과 피보험단위기간 등이 기록되는 상용근로자의 실업급여 판단 서류로 설명합니다. 회사가 퇴사자에게 주는 경력증명서나 퇴직증명서와 역할이 다릅니다.','실업급여 신청을 준비한다면 고용보험 피보험자격 상실 신고와 이직확인서가 처리됐는지를 구분해 봅니다. 두 절차가 비슷한 시기에 진행돼도 같은 문서는 아닙니다.'],
['먼저 처리 상태를 조회하세요',table('이직확인서 확인 순서',[['처리 여부','고용24 개인서비스에서 제출·처리 상태 확인'],['이직일','실제 마지막 근무와 자격상실 시점 대조'],['이직 사유','권고사직·계약만료·자진퇴사 등 실제 경위 대조'],['임금 자료','급여명세서와 평균임금 기초자료 비교'],['피보험단위기간','유급일 등이 포함된 산정 내용을 확인']]),'화면 메뉴 이름은 개편될 수 있으므로 고용24에서 ‘이직확인서 처리여부 조회’를 검색해 현재 경로를 이용합니다. 화면 캡처를 공개 게시판에 올릴 때는 주민등록번호와 사업장 정보를 가리세요.'],
['아직 제출되지 않았다면 회사에 요청합니다','근로자는 사업주에게 이직확인서 발급을 요청할 수 있습니다. 요청 날짜와 전달 방법을 기록하고 회사 인사·급여 담당자에게 처리 예정일을 확인하세요. 퇴사 직후 바로 조회되지 않는다고 같은 요청을 여러 담당자에게 반복하기보다는 처리 주체를 정해 확인하는 편이 낫습니다.','회사가 문서 이름을 혼동하면 실업급여 수급자격 판단용 이직확인서라고 명확히 설명하세요. 계속 처리되지 않을 때는 관할 고용센터에 현재 상태와 요청 자료를 가지고 상담합니다.'],
['내용이 다르면 차이를 항목별로 정리하세요','실제는 계약기간 만료인데 개인 사정 퇴사로 적혔거나, 근무기간·임금이 다른 경우처럼 틀린 항목과 맞는 자료를 한 줄씩 대응시킵니다. 근로계약서, 사직서, 권고사직 통보, 급여명세서와 출근기록 등이 상황에 따라 도움이 될 수 있습니다.','사업주에게 사실에 맞는 정정을 요청하고, 이견이 계속되면 고용센터에 자료를 제출해 사실관계 확인 절차를 안내받습니다. 단순히 본인에게 유리한 코드로 바꿔 달라고 요구하는 것은 정정이 아닙니다.'],
['이직확인서 외 요건도 함께 점검하세요','서류가 정상 처리돼도 피보험단위기간, 재취업 의사와 능력, 구직활동 등 수급요건은 별도로 판단됩니다. 반대로 문서 내용에 이견이 있다고 신청 자체를 포기할 필요도 없습니다. 현재 자료를 기준으로 상담을 시작할 수 있습니다.','퇴사 사유가 복잡하면 사건의 순서를 날짜별로 한 장에 정리하세요. 누가 언제 무엇을 통보했고 본인은 어떻게 대응했는지 설명하면 상담 과정에서 빠진 자료를 찾기 쉽습니다.'],
['처리 완료 후에도 원자료를 보관하세요','조회 화면의 처리 완료 표시는 문서가 접수됐다는 뜻이지 모든 내용에 이견이 없다는 뜻은 아닙니다. 신청 과정에서 확인한 항목과 제출한 자료의 사본, 회사에 정정을 요청한 날짜를 보관하세요. 담당자가 추가 확인을 요청할 때 같은 사실을 일관되게 설명하는 데 도움이 됩니다.','임금이나 근무일수 차이가 있다면 본인이 임의로 평균임금을 다시 확정하기보다 어떤 지급내역이 빠졌다고 보는지 표시합니다. 계산과 법적 판단은 공식 담당기관에서 확인하고, 개인정보가 담긴 화면은 가족이라도 필요 이상 공유하지 마세요.']
],[['이직확인서가 없으면 실업급여 신청을 못 하나요?','처리 상태가 수급 판단에 필요합니다. 회사에 발급을 요청하고 지연될 경우 관할 고용센터에 절차를 문의하세요.'],['회사에서 자진퇴사로 적으면 끝인가요?','사업주 기재만으로 최종 판단이 자동 확정되는 것은 아닙니다. 실제 경위와 객관적 자료를 정리해 확인을 요청할 수 있습니다.'],['경력증명서와 같은 문서인가요?','다릅니다. 이직확인서는 실업급여 판단에 필요한 이직 사유와 임금·피보험단위기간 등을 담는 문서입니다.']],
[['고용24 이직확인서 제도 안내','https://www.work24.go.kr/cm/c/f/1100/selecSystInfo.do?systId=SI00000343'],['고용24 실업급여 안내','https://ei.work24.go.kr/ei/eih/eg/pb/pbPersonBnef/retrievePb0201Info.do']],['실업급여-신청-전-확인할-것','자발적-퇴사-실업급여-인정사유-증빙','퇴직금-지급기한-미지급-신고']),

post('퇴직금-irp-계좌-수령-예외','퇴직금 IRP 계좌로 받아야 하는 경우와 예외','money','퇴직금 수령 계좌','severance-irp','IRP 의무·예외 사유·수령 계획','퇴직금을 IRP 계좌로 받는 원칙과 55세 이후 퇴직 등 예외, 계좌 개설 전 확인할 사항을 정리했습니다.','퇴직금이 일반 급여통장으로 바로 들어올 것이라고 예상했다면 회사에 지급 방식을 먼저 확인하세요. 현재는 원칙적으로 근로자가 지정한 IRP 계정으로 이전하는 구조입니다.',[
['퇴직금 지급기한과 수령계좌는 다른 문제입니다','퇴직금은 원칙적으로 퇴직일부터 14일 이내 지급해야 하고, 당사자 합의로 기한을 연장할 수 있습니다. 지급 시기는 기존 퇴직금 글에서 확인하고, 이번에는 돈을 어느 계좌로 받는지를 구분해 살펴봅니다.','고용노동부 상담 안내에 따르면 2022년 4월 14일부터 퇴직금은 근로자가 지정한 개인형퇴직연금제도 계정 등으로 지급하는 것이 원칙입니다. 회사가 IRP 계좌 사본을 요청한다면 상품 가입 권유인지 법정 지급 절차인지 먼저 확인하세요.'],
['IRP 이전 예외를 확인하세요',table('IRP 이전 확인 메모',[['퇴직 당시 나이','55세 이후 퇴직인지 확인'],['퇴직급여 금액','300만원 이하 예외 해당 여부 확인'],['특별 사유','사망·국외 출국 등 공식 예외와 관련되는지 확인'],['지급 계좌','본인 명의 IRP 계좌 정보 확인'],['지급 시점','퇴직일과 합의된 지급기한 기록']]),'예외에 해당한다고 해서 무조건 일반 통장으로 받아야 한다는 뜻은 아닙니다. 반대로 개인 사정으로 IRP 개설이 번거롭다는 이유만으로 예외가 되는 것도 아닙니다. 회사와 퇴직연금사업자에게 적용 절차를 확인하세요.'],
['계좌를 만들기 전에 용도를 구분하세요','퇴직급여 수령용 IRP와 재직 중 세액공제를 위해 납입하는 개인 IRP는 같은 이름 때문에 혼동하기 쉽습니다. 금융회사 화면에서 수령 목적, 수수료, 운용 가능한 상품과 해지·이전 절차를 확인합니다. 특정 금융회사의 상품을 이 글에서 추천하지 않습니다.','회사에서 지정한 한 곳만 가능하다고 안내한다면 법적 필수인지 업무 편의를 위한 안내인지 질문하세요. 근로자는 지급받을 계정을 지정하는 과정에서 필요한 정보를 충분히 확인할 필요가 있습니다.'],
['입금 후 바로 인출하기 전에 세금을 확인하세요','IRP에 퇴직급여가 들어온 뒤 일시금으로 받을지 연금 형태로 유지할지는 세금과 생활자금 계획에 영향을 줄 수 있습니다. 단순히 계좌가 불편하다는 이유로 즉시 해지하기 전에 퇴직소득세 처리와 연금 수령 요건을 금융회사·국세청 공식 안내로 확인하세요.','퇴직금 전액을 생활비로 써야 하는 사람과 다른 노후자금이 있는 사람의 판단은 다릅니다. 대출 상환, 건강보험료, 당장 필요한 현금을 함께 적어보고 결정하세요.'],
['회사에서 지급하지 않으면 별도 대응이 필요합니다','IRP 계좌를 제출했는데도 지급기한이 지났다면 계좌 문제와 미지급 문제를 분리합니다. 회사에 지급 예정일과 지연 사유를 서면으로 확인하고, 해결되지 않으면 고용노동부 노동포털의 임금·퇴직금 진정 절차를 검토하세요.','IRP 이전 원칙은 회사가 퇴직금을 늦게 지급해도 된다는 뜻이 아닙니다. 계좌 개설 요청을 받았다면 가능한 시점에 정확한 정보를 제출하고 기록을 남기세요.'],
['퇴직 전 한 장으로 수령 계획을 정리하세요','퇴직일, 예상 퇴직급여, IRP 예외 해당 여부, 제출할 계좌와 회사 담당자를 한 장에 적습니다. IRP 계좌를 새로 만들었다면 금융회사 이름과 계좌 용도를 확인하고 회사에는 필요한 정보만 안전한 방법으로 전달하세요.','입금 뒤 일시금 인출을 생각한다면 예상 세금과 생활비 사용처를 함께 적습니다. 광고에서 말하는 절세 효과만 보고 장기간 유지하거나, 반대로 세금을 확인하지 않고 바로 해지하는 두 선택 모두 피하고 본인의 현금흐름에 맞춰 결정하세요.']
],[['55세가 넘으면 IRP를 만들 필요가 없나요?','공식 예외에 해당할 수 있지만 실제 지급 방식은 회사와 퇴직연금사업자에 확인하세요. 예외는 IRP 사용 금지가 아닙니다.'],['퇴직금이 300만원 이하면 일반 통장으로 받나요?','소액 예외에 해당할 수 있습니다. 금액 산정과 회사의 지급 절차를 확인해야 합니다.'],['IRP에 들어온 돈을 바로 찾을 수 있나요?','인출 가능 여부뿐 아니라 세금과 해지 절차가 관계됩니다. 금융회사와 국세청 공식 안내를 확인한 뒤 결정하세요.']],
[['고용노동부 퇴직금 IRP 이전 안내','https://1350.moel.go.kr/rtmview.do?id=1000291955'],['고용노동부 퇴직연금 제도 안내','https://www.moel.go.kr/retirementpay.do']],['퇴직금-지급기한-미지급-신고','퇴직금-중간정산과-퇴직연금-차이','퇴직-후-생활비-계산법']),

post('퇴직연금-db형-dc형-차이','퇴직연금 DB형 DC형 차이와 퇴사 전 확인할 항목','money','퇴직연금 유형 비교','retirement-db-dc','제도 유형·적립 내역·운용 책임','DB형과 DC형의 급여 계산과 운용 책임을 비교하고 퇴사 전에 확인할 적립 내역과 수령 절차를 정리했습니다.','회사에서 퇴직연금에 가입했다고 해도 DB형과 DC형은 돈이 쌓이고 관리되는 방식이 다릅니다. 먼저 내 제도 유형을 확인해야 예상 퇴직급여와 점검 항목을 제대로 볼 수 있습니다.',[
['DB형은 받을 급여, DC형은 넣을 부담금이 중심입니다','고용노동부는 DB형을 퇴직 시 받을 급여가 사전에 정해지고 사용자가 적립금을 운용하는 제도로 안내합니다. DC형은 사용자가 매년 근로자 연간 임금총액의 12분의 1 이상을 부담금으로 납입하고 근로자가 자신의 계정 운용을 선택하는 구조입니다.','DB형은 회사의 운용 성과가 낮다고 근로자의 법정 급여가 그대로 줄어드는 방식이 아닙니다. DC형은 납입된 부담금과 운용 결과가 최종 금액에 영향을 줍니다. 어느 쪽이 항상 유리하다고 단정할 수 없습니다.'],
['내 유형과 적립 상태를 확인하세요',table('퇴직연금 점검표',[['제도 유형','DB·DC·중소기업퇴직연금기금 여부'],['가입 사업자','관리하는 금융기관과 계정 접근 방법'],['납입 내역','DC형은 연도별 회사 부담금과 누락 여부'],['예상 급여','DB형은 평균임금·근속기간 기초자료'],['수령 절차','퇴직일·IRP 계좌·신청 서류']]),'급여명세서에 퇴직연금이라는 단어가 없다고 미가입으로 단정하지 마세요. 회사 인사 담당자와 퇴직연금사업자의 가입자 화면에서 확인합니다. 회사가 매년 제공해야 하는 교육자료도 제도 이해에 활용할 수 있습니다.'],
['DC형은 상품을 방치하지 않았는지 봅니다','DC형에서는 근로자가 운용 지시를 하지 않거나 오래된 선택을 그대로 두면 현재의 위험감수 수준과 맞지 않을 수 있습니다. 수익률만 보고 바꾸기보다 원리금 보장 여부, 손실 가능성, 수수료와 퇴직 예정 시점을 함께 확인하세요.','투자상품 선택은 개인의 자산과 위험 성향에 따라 다릅니다. 이 글은 특정 상품 매수나 수익을 권하지 않습니다. 이해하지 못한 상품으로 한 번에 옮기기보다 퇴직연금사업자의 설명과 공시자료를 확인하세요.'],
['DB형은 임금과 근속자료를 확인하세요','DB형의 예상 급여를 볼 때는 퇴직 시점의 평균임금과 계속근로기간이 중요합니다. 최근 임금 변동, 휴직기간, 상여금·수당 반영 여부처럼 계산에 영향을 줄 수 있는 자료를 모읍니다. 온라인 계산기는 입력값이 맞아야 의미가 있습니다.','회사 적립금 운용 현황과 근로자 개인의 법정 급여 계산을 혼동하지 마세요. 예상액이 이해되지 않으면 회사가 사용한 임금과 기간 자료를 요청해 항목별로 대조합니다.'],
['퇴사 전에는 수령 절차까지 확인합니다','퇴직 예정일, 마지막 임금 정산, 퇴직급여 산정자료, IRP 제출 시점과 지급 예정일을 한 번에 확인합니다. DC형이라면 마지막 사업연도 부담금이 언제 반영되는지도 질문하세요.','퇴직 후에는 회사 시스템 접근이 어려울 수 있으므로 합법적으로 받을 수 있는 가입 확인서와 납입 내역을 미리 보관합니다. 예상액과 실제액이 다르면 유형별 계산 구조를 기준으로 차이를 확인하세요.'],
['유형 변경 권유는 이유부터 확인하세요','재직 중 DB형에서 DC형으로 전환하거나 추가 운용을 권유받았다면 회사 제도 변경인지 개인 선택인지부터 구분합니다. 과거 근속분의 처리, 전환 기준일과 되돌릴 수 있는지 여부를 서면 자료로 확인하세요. 단기 수익률만으로 장기 제도를 바꾸면 판단 근거가 약해질 수 있습니다.','설명회 자료에 예상 수익이 제시돼도 보장 수익으로 받아들이면 안 됩니다. 수수료와 손실 가능성, 퇴직까지 남은 기간을 확인하고 이해되지 않는 부분은 퇴직연금사업자의 공식 상담 창구에 질문하세요.']
],[['DB형과 DC형 중 무엇이 더 좋은가요?','임금 흐름, 이직 가능성, 운용 책임과 위험 성향에 따라 달라집니다. 한 가지 유형이 모두에게 유리하지 않습니다.'],['DC형이면 회사가 퇴직금을 책임지지 않나요?','회사는 법에서 정한 부담금을 납입할 의무가 있습니다. 근로자는 적립금 운용 결과의 영향을 받습니다.'],['내가 어떤 유형인지 어디서 확인하나요?','회사 인사 담당자, 가입자 교육자료와 퇴직연금사업자의 본인 계정에서 확인하세요.']],
[['고용노동부 퇴직연금 제도 안내','https://www.moel.go.kr/retirementpay.do'],['고용노동부 DB·DC·IRP 비교 카드뉴스','https://www.moel.go.kr/news/cardinfo/view.do?bbs_seq=20220300928']],['퇴직금-irp-계좌-수령-예외','퇴직금-중간정산과-퇴직연금-차이','4050-생활경제-점검표']),

post('건강보험-본인부담상한제-환급금-신청','건강보험 본인부담상한제 환급금 조회와 신청방법','welfare','의료비 환급 확인','medical-cap-refund','지급 대상·제외 비용·신청 계좌','건강보험 본인부담상한제의 사전급여와 사후환급, 제외되는 비용과 지급 신청 순서를 정리했습니다.','병원비를 많이 냈다고 모든 금액이 자동으로 환급되는 것은 아닙니다. 건강보험이 적용된 본인부담금인지, 상한제에서 제외되는 항목인지부터 나누어 확인하세요.',[
['본인부담상한제는 연간 급여 본인부담을 기준으로 봅니다','본인부담상한제는 한 해 동안 부담한 건강보험 적용 본인일부부담금이 개인별 상한액을 넘을 때 초과액을 공단이 부담하는 제도입니다. 의료기관이 상한액을 넘는 금액을 공단에 청구하는 사전급여와, 다음 해 정산 후 공단이 지급하는 사후환급 방식이 있습니다.','개인별 상한액은 소득 수준과 요양병원 입원일수 등에 따라 달라질 수 있습니다. 다른 사람의 환급액을 내 기준으로 적용하지 말고 공단 조회 결과를 확인하세요.'],
['환급 대상에서 빠지는 비용이 있습니다',table('의료비 구분 메모',[['건강보험 급여','본인일부부담금의 연간 합계 확인'],['비급여','상급병실 차액 등 상한제 제외 여부 확인'],['선별급여 등','공단 안내의 제외 항목과 대조'],['다른 지원금','국가·지자체 의료비 지원과 중복 정산 확인'],['요양병원','연간 입원일수에 따른 상한 기준 확인']]),'실손보험에서 받은 금액과 본인부담상한제 환급의 관계는 보험계약과 정산 시점에 따라 확인할 사항이 생길 수 있습니다. 보험회사 안내만 듣고 공단 환급 대상 자체를 포기하지 말고 각각의 공식 창구에서 확인하세요.'],
['안내문을 받았다면 지급 정보를 확인하세요','공단이 사후환급 지급대상자에게 보낸 신청서에는 진료받은 사람의 인적사항과 지급받을 계좌를 기재합니다. 방문, 전화, 인터넷, 팩스와 우편 등 공단이 안내하는 방법을 이용할 수 있습니다. 문자 링크가 의심스러우면 클릭하지 말고 공단 홈페이지나 대표번호로 직접 확인하세요.','본인 명의 계좌 사용이 기본입니다. 치매나 의식불명 등 부득이한 사유로 가족 계좌를 이용하려면 진단서, 가족관계증명서, 위임장 등 추가 자료가 필요할 수 있으므로 먼저 지사에 확인합니다.'],
['안내문이 없어도 공식 조회를 이용하세요','국민건강보험 홈페이지나 앱의 환급금 조회·신청 메뉴에서 미지급 환급금이 있는지 확인할 수 있습니다. 가족의 의료비를 대신 관리하더라도 본인 인증과 위임 범위를 지켜야 합니다. 계좌번호와 주민등록번호를 일반 검색창이나 비공식 사이트에 입력하지 마세요.','최근 진료비는 소득구간 확정과 연간 정산 전이라 바로 사후환급 대상으로 표시되지 않을 수 있습니다. 언제 기준으로 조회한 결과인지 기록하고 공단 안내 시점을 확인하세요.'],
['환급액이 예상과 다르면 항목별로 묻습니다','연간 병원비 총액, 건강보험 급여 본인부담금, 제외 비용, 개인별 상한액을 나누어 질문하세요. 단순히 총 병원비에서 상한액을 빼면 실제 환급액과 다를 수 있습니다.','병원 영수증과 진료비 세부내역서를 보관하면 급여·비급여를 구분하는 데 도움이 됩니다. 이 글은 개인별 환급액을 계산하지 않으며 최종 금액은 국민건강보험공단 조회 결과를 기준으로 확인합니다.'],
['가족 의료비를 관리할 때는 연도별로 묶습니다','여러 병원을 이용했다면 진료받은 사람과 진료 연도를 기준으로 영수증을 나눕니다. 본인부담상한제는 가구 전체 병원비를 한꺼번에 더하는 방식이 아니므로 부모님과 자녀의 비용을 섞지 마세요. 환급 안내문과 입금 내역도 같은 연도 묶음에 보관합니다.','주소나 연락처가 바뀌었다면 공단에 현재 정보가 반영됐는지 확인합니다. 환급을 미끼로 계좌 비밀번호나 보안카드를 요구하는 연락은 응하지 말고, 공단 공식 홈페이지와 대표번호를 통해 진위를 확인하세요.']
],[['비급여 병원비도 모두 합산되나요?','아닙니다. 비급여 등 상한제에서 제외되는 항목이 있으므로 공단의 적용 내역을 확인해야 합니다.'],['환급금은 자동으로 입금되나요?','지급동의 계좌 등록 등 상황에 따라 다를 수 있습니다. 안내문이나 공식 조회 화면에서 신청 필요 여부를 확인하세요.'],['부모님 환급금을 자녀 계좌로 받을 수 있나요?','부득이한 사유에는 추가 증빙이 필요할 수 있습니다. 공단 지사에 필요한 자료와 계좌 조건을 먼저 확인하세요.']],
[['국민건강보험공단 본인부담상한제 안내','https://www.nhis.or.kr/static/html/wbma/c/wbmac0209.html'],['국민건강보험공단 홈페이지','https://www.nhis.or.kr/']],['재난적의료비-지원-신청조건-준비서류','건강보험-피부양자-탈락-기준-4050-체크','부모님-복지-점검-가이드']),

post('재난적의료비-지원-신청조건-준비서류','재난적의료비 지원 신청조건과 준비서류','support','고액 의료비 지원','catastrophic-medical','소득·재산·의료비·신청기한','재난적의료비 지원의 대상 기준과 제외 비용, 퇴원 후 신청기한과 준비서류 확인 순서를 안내합니다.','갑작스러운 입원이나 치료로 가계 부담이 커졌다면 재난적의료비 지원을 확인해볼 수 있습니다. 질병 이름 하나가 아니라 소득·재산·의료비 부담과 지원 제외 항목을 함께 심사합니다.',[
['본인부담상한제와 다른 제도입니다','본인부담상한제는 건강보험 급여 본인부담금의 연간 상한을 적용하는 제도입니다. 재난적의료비 지원은 소득 수준에 비해 과도한 의료비가 발생한 가구를 대상으로 일부 의료비를 지원하며 별도 신청과 심사를 거칩니다.','두 제도를 같은 환급금으로 생각하면 신청 시기와 준비자료를 놓칠 수 있습니다. 이미 받은 국가·지자체 지원이나 민간보험금은 지원금 산정 과정에서 확인 대상이 될 수 있습니다.'],
['네 가지 기준을 함께 확인하세요',table('재난적의료비 상담 준비',[['진료 범위','입원·외래와 대상 질환 범위 확인'],['소득 기준','가구원과 건강보험료 기준 확인'],['재산 기준','가구 재산 과표 합산 기준 확인'],['의료비 부담','인정되는 본인부담의료비를 구분'],['신청 시기','최종 진료일 또는 퇴원일 다음 날부터 기한 확인']]),'기준중위소득이나 재산 숫자는 개정될 수 있고 예외 심사도 있을 수 있습니다. 오래된 블로그 표를 그대로 적용하지 말고 진료가 발생한 시점의 국민건강보험공단 안내를 확인하세요.'],
['지원 제외 비용을 먼저 나눕니다','미용·성형, 간병료, 일부 상급병실료와 제도 취지에 맞지 않는 비용 등은 지원에서 제외될 수 있습니다. 병원비 전체가 지원대상 금액이 되는 것이 아닙니다. 영수증만 보지 말고 진료비 세부내역서를 준비하세요.','실손보험금, 다른 의료비 지원과 중복되는 금액도 확인합니다. 아직 보험금이 확정되지 않았다면 지급 예정 여부를 숨기지 말고 신청 창구에 처리 방법을 문의하세요.'],
['퇴원 후 신청기한을 놓치지 마세요','공식 안내는 원칙적으로 퇴원일 또는 최종 진료일 다음 날부터 180일 이내 신청하도록 설명합니다. 장기간 입원 중 신청이 필요한 경우에는 입원 중 신청 가능 조건을 공단 지사에 확인하세요.','서류를 완벽하게 만들 때까지 기다리다 기한을 넘기지 않도록 먼저 상담 날짜를 잡습니다. 병원 의료사회복지팀이 있는 경우 신청 지원을 받을 수 있는지도 문의할 수 있습니다.'],
['신청 서류는 개인 상황에 따라 달라집니다','지급신청서, 진단서, 입퇴원확인서, 진료비 영수증·세부내역서, 가족관계와 보험금 관련 자료 등이 필요할 수 있습니다. 모든 사람에게 같은 서류가 필요한 것은 아니므로 공단 지사에서 본인 목록을 확인하세요.','서류 발급비도 들 수 있으므로 이미 병원에서 받은 자료와 추가 발급할 자료를 나눕니다. 주민등록번호와 진료정보가 담긴 서류는 이메일·메신저로 무분별하게 보내지 마세요.'],
['접수 후에는 보완 요청과 결정 내용을 확인합니다','서류를 냈다고 바로 지원금이 확정되는 것은 아닙니다. 심사 과정에서 소득·재산, 보험금과 다른 지원 여부를 확인하거나 추가 자료를 요청할 수 있습니다. 연락 가능한 번호를 유지하고 보완 요청의 제출기한을 기록하세요.','지급 결정서에는 인정된 비용과 제외된 비용이 구분될 수 있습니다. 예상과 다르면 단순히 금액만 묻지 말고 어느 진료비 항목이 어떤 이유로 제외됐는지 확인해야 다음 의료비 지원 상담에도 활용할 수 있습니다.']
],[['모든 질병이 지원 대상인가요?','입원과 외래의 적용 범위가 다를 수 있고 소득·재산·의료비 기준도 함께 심사합니다. 공단에 진료 형태를 알려 확인하세요.'],['병원비의 전액을 지원받나요?','아닙니다. 인정되는 비용과 지원 비율, 제외 항목을 심사하며 다른 지원·보험금도 확인될 수 있습니다.'],['퇴원 후 언제까지 신청하나요?','원칙적으로 퇴원일 또는 최종 진료일 다음 날부터 180일 이내입니다. 개인 상황의 기산일은 공단에 확인하세요.']],
[['국민건강보험공단 재난적의료비 지원 안내','https://www.nhis.or.kr/static/html/wbda/h/wbdah0101.html'],['재난적의료비 지원에 관한 법률 시행규칙','https://www.nhis.or.kr/lm/lmxsrv/law/lawFullContent.do?SEQ=477']],['건강보험-본인부담상한제-환급금-신청','부모님-긴급복지-신청-전-확인할-것','부모님-주민센터-복지상담-준비물']),

post('장기요양-본인부담금-감경-확인방법','장기요양 본인부담금 감경 대상과 확인방법','welfare','장기요양 비용 감경','ltc-copay-reduction','자격 구분·감경률·적용 시기','장기요양 본인부담금 감경 대상과 재가·시설급여 부담 구조, 적용 여부 확인 순서를 정리했습니다.','장기요양등급을 받았더라도 이용 비용이 모두 무료가 되는 것은 아닙니다. 일반 대상, 감경 대상과 의료급여 수급자의 본인부담 구조를 구분해 확인해야 합니다.',[
['본인부담금은 급여 종류에 따라 다릅니다','장기요양보험에서 재가급여와 시설급여는 기본 본인부담 비율이 다릅니다. 여기에 의료급여 자격이나 소득·재산 수준 등에 따른 감경이 적용될 수 있습니다. 식사재료비, 상급침실료 등 비급여 항목은 장기요양 급여 본인부담과 별도로 봐야 합니다.','기관이 제시한 월 예상액만 보지 말고 급여비용, 본인부담률, 비급여와 월 한도 초과액을 나누어 설명받으세요. 이용일수와 서비스가 바뀌면 실제 부담액도 달라질 수 있습니다.'],
['현재 자격과 고지 내용을 확인하세요',table('장기요양 비용 확인표',[['급여 종류','방문요양·주야간보호·시설급여 등'],['자격 구분','일반·감경·의료급여 자격 표시'],['본인부담률','공단의 현재 적용 비율 확인'],['비급여','식사·상급침실 등 별도 항목'],['월 한도','등급별 한도와 초과 이용 여부']]),'장기요양 인정서와 개인별장기요양이용계획서, 최근 비용명세서를 함께 보면 적용 상태를 확인하기 쉽습니다. 보호자가 대신 문의할 때는 수급자 정보와 위임이 필요한 범위를 먼저 확인하세요.'],
['감경은 공식 자격 기준으로 적용됩니다','노인장기요양보험법과 관련 고시는 의료급여 수급권자, 소득·재산 등이 일정 기준 이하인 사람 등에게 본인부담금을 감경할 수 있도록 정합니다. 단순히 생활비가 빠듯하다는 설명만으로 기관이 임의로 할인하는 제도는 아닙니다.','장기요양기관이 이용자를 모집하려고 법정 본인부담금을 임의로 면제하거나 깎아주는 제안은 주의해야 합니다. 공단에서 확인되는 자격과 비용명세서를 기준으로 봅니다.'],
['적용 시기와 변동 여부를 확인하세요','건강보험 자격과 보험료·재산 자료 등이 변하면 감경 적용 여부가 달라질 수 있습니다. 언제부터 적용 또는 제외됐는지, 이미 납부한 금액의 정산이 있는지를 공단에 확인하세요.','가족이 예상한 시점과 기관 청구 시점이 다르면 자격 적용일, 서비스 제공일과 청구월을 나누어 질문합니다. 구두 설명만 듣지 말고 비용명세서를 보관하세요.'],
['계약 전에 총비용을 다시 계산합니다','감경이 적용돼도 비급여와 월 한도 초과분까지 모두 줄어드는 것은 아닙니다. 기관 계약서에서 급여·비급여 항목, 추가 비용, 중도 퇴소 정산과 납부일을 확인합니다.','이용 중 서비스 종류나 횟수를 바꾸면 새 예상 비용표를 요청하세요. 이 글은 개인별 감경 자격이나 월 납부액을 확정하지 않으며, 최종 적용 상태는 국민건강보험공단 장기요양보험에서 확인합니다.'],
['명세서에서 감경 적용을 직접 확인하세요','기관이 발급한 비용명세서에서 총 급여비용, 공단부담금, 본인부담금과 비급여를 순서대로 봅니다. 감경 대상이라고 들었는데 일반 비율로 계산된 것처럼 보이면 기관에 자격 적용일과 청구 내역을 문의하고 공단에도 현재 자격을 확인하세요.','자동이체 금액만 보고 정상 적용됐다고 판단하지 마세요. 서비스가 추가되거나 결석·입원으로 이용일수가 바뀌면 금액도 변할 수 있으므로 월별 제공기록과 명세서를 함께 보관합니다.']
],[['장기요양등급이 있으면 비용이 무료인가요?','아닙니다. 기본 본인부담이 있고 자격에 따라 감경·면제가 적용될 수 있으며 비급여는 별도입니다.'],['기관에서 본인부담금을 할인해준다고 합니다','법정 본인부담금의 임의 면제·할인은 주의해야 합니다. 공단 자격과 공식 비용명세서를 확인하세요.'],['감경 대상인지 어디서 확인하나요?','국민건강보험공단 장기요양보험의 본인 자격과 기관 비용명세서에서 확인하고 불명확하면 공단에 문의하세요.']],
[['국민건강보험공단 장기요양 본인부담금 감경 고시','https://www.nhis.or.kr/lm/lmxsrv/createHwpChoice.do?SEQ_HISTORY=22891'],['찾기쉬운 생활법령 장기요양 시설급여 안내','https://easylaw.go.kr/CSP/CnpClsMain.laf?ccfNo=3&cciNo=2&cnpClsNo=1&csmSeq=2856&popMenu=ov'],['노인장기요양보험 공식 홈페이지','https://www.longtermcare.or.kr/']],['장기요양등급-신청-전-확인할-것','방문요양-주간보호센터-비용-비교','장기요양-가족휴가제-이용방법']),

post('요양원-요양병원-차이-비용-입소기준','요양원과 요양병원 차이 비용과 입소 기준 비교','welfare','부모님 돌봄기관 비교','nursing-home-hospital','돌봄 목적·의료 필요·적용 보험','요양원과 요양병원의 목적, 입소·입원 기준, 의료인 상주와 적용 보험 및 비용 확인방법을 비교했습니다.','요양원과 요양병원은 이름이 비슷하지만 목적과 적용 제도가 다릅니다. 부모님의 현재 의료 필요와 일상생활 도움 중 무엇이 중심인지 먼저 구분하세요.',[
['요양원은 돌봄, 요양병원은 의료가 중심입니다','찾기쉬운 생활법령정보는 요양원을 시설급여를 제공하는 장기요양기관으로, 요양병원을 입원환자에게 의료행위를 제공하는 의료기관으로 구분합니다. 요양원은 일상생활 돌봄이 중심이고 요양병원은 의사의 판단에 따른 입원 치료가 중심입니다.','한쪽이 다른 쪽보다 무조건 좋은 시설이라는 비교가 아닙니다. 부모님의 건강 상태, 의료 처치 필요와 일상생활 수행능력에 맞는 유형을 먼저 선택해야 합니다.'],
['입소·입원 조건과 보험이 다릅니다',table('요양원과 요양병원 비교',[['주된 목적','요양원은 돌봄, 요양병원은 의료적 치료'],['이용 조건','요양원은 시설급여 가능한 장기요양등급 확인'],['적용 보험','요양원은 장기요양보험, 요양병원은 건강보험'],['의료인','요양병원은 의료기관으로 의료인 상주'],['비용 확인','각 보험 본인부담과 비급여를 별도로 확인']]),'장기요양등급이 있다고 요양병원 입원비에 장기요양 시설급여가 적용되는 것은 아닙니다. 반대로 의료 처치가 필요한데 비용만 보고 요양원을 선택해서도 안 됩니다.'],
['비용표는 같은 항목끼리 비교하세요','요양원은 장기요양 급여 본인부담과 식사재료비·상급침실료 같은 비급여를 나눠 봅니다. 요양병원은 건강보험 적용 진료비, 식대, 간병 관련 비용과 비급여를 구분합니다. 두 곳의 월 총액만 비교하면 포함 항목이 달라 판단하기 어렵습니다.','상담할 때 기본 월 예상액뿐 아니라 기저귀, 간병, 식사, 상급 병실, 치료·검사와 외부 진료 비용이 어디에 포함되는지 적어달라고 요청하세요. 실제 이용일수와 상태 변화에 따라 달라질 수 있습니다.'],
['부모님의 하루를 기준으로 질문하세요','식사·이동·배변에 얼마나 도움이 필요한지, 욕창·산소·투석·재활 등 의료 처치가 필요한지, 밤에 위험 행동이 있는지 정리합니다. 가족이 원하는 편의보다 부모님의 안전과 치료 필요를 우선합니다.','요양원 상담에는 장기요양 인정서와 이용계획서를, 요양병원 상담에는 진료기록과 현재 처방을 준비할 수 있습니다. 의료적 판단은 담당 의사와 상의하고 약을 가족이 임의로 바꾸지 마세요.'],
['기관 유형을 정한 뒤 개별 시설을 비교합니다','같은 요양원이나 요양병원이라도 인력, 프로그램, 면회, 응급 대응과 비용이 다릅니다. 공단 기관검색과 의료기관 공식 정보를 이용해 행정처분·평가 정보, 거리와 대기 여부를 확인하세요.','계약 전 실제 공간을 보고 담당 인력과 야간 대응, 보호자 연락 방식, 퇴소·전원 절차를 질문합니다. 광고 문구나 한 번의 후기만으로 결정하지 말고 두세 곳을 같은 질문표로 비교하세요.'],
['상태가 바뀌면 기관 유형도 다시 검토합니다','요양원 생활 중 의료 처치 필요가 커지거나, 요양병원 치료 후 상태가 안정되면 현재 기관이 계속 맞는지 다시 상담할 수 있습니다. 처음 선택이 평생 고정되는 것은 아닙니다. 담당 의사와 장기요양 담당자에게 전원·퇴소 시 필요한 자료와 시점을 확인하세요.','가족은 비용과 거리뿐 아니라 부모님의 적응 상태와 의사를 함께 기록합니다. 갑작스러운 건강 악화 때 어느 병원으로 이송하는지, 반대로 회복 후 지역사회 복귀나 재가 돌봄이 가능한지도 계약 전에 물어보면 이후 결정을 준비하기 쉽습니다.']
],[['장기요양등급이 있으면 요양병원 비용이 줄어드나요?','요양병원에는 장기요양 시설급여가 적용되지 않습니다. 건강보험 적용과 병원 비용을 별도로 확인하세요.'],['요양원에도 의사가 항상 있나요?','요양원은 의료기관이 아니며 요양병원과 인력 기준이 다릅니다. 계약할 시설의 의료 연계와 응급 대응을 확인하세요.'],['비용이 싼 곳을 선택하면 될까요?','포함 항목과 부모님의 의료·돌봄 필요가 다르므로 총액만 비교하지 말고 급여·비급여와 제공 내용을 대조하세요.']],
[['찾기쉬운 생활법령 요양원·요양병원 비교','https://www.easylaw.go.kr/CSP/OnhunqueansInfoRetrieve.laf?onhunqnaAstSeq=97&onhunqueSeq=6500&search_put='],['찾기쉬운 생활법령 장기요양기관 선택','https://www.easylaw.go.kr/CSP/CnpClsMain.laf?ccfNo=3&cciNo=2&cnpClsNo=1&csmSeq=2038&menuType=cnpcls&popMenu=ov'],['노인장기요양보험 기관 찾기','https://www.longtermcare.or.kr/']],['장기요양등급-신청-전-확인할-것','장기요양-본인부담금-감경-확인방법','부모님-복지-점검-가이드']),

post('생활지원사-하는일-채용공고-근무조건','생활지원사 하는 일과 채용공고에서 확인할 근무조건','rejob','돌봄 일자리 준비','care-support-worker','담당 업무·계약기간·이동 조건','노인맞춤돌봄서비스 생활지원사의 업무와 채용공고에서 확인할 계약기간, 근무시간, 이동 및 우대조건을 정리했습니다.','생활지원사는 요양보호사와 이름이 비슷하지만 담당 사업과 업무 범위가 다릅니다. 자격증 유무만 보기보다 실제 공고의 담당 지역과 이동, 근무시간을 확인하세요.',[
['노인맞춤돌봄서비스 수행인력입니다','보건복지부는 노인맞춤돌봄서비스 수행인력으로 전담사회복지사와 생활지원사를 안내합니다. 생활지원사는 안전·안부 확인, 사회참여, 생활교육, 외출동행과 가사활동 지원 등 기관의 서비스 계획에 따른 업무를 수행합니다.','가정에서 장기요양급여를 제공하는 방문요양보호사와 같은 직무로 단정하면 안 됩니다. 채용 기관, 대상자와 사업지침에 따라 담당 내용이 정해집니다.'],
['공고에서 다섯 가지를 비교하세요',table('생활지원사 공고 비교표',[['계약 형태','기간제 여부와 사업기간·갱신 조건'],['근무시간','주 소정근로시간과 실제 일정'],['담당 지역','방문 권역과 이동 거리·교통수단'],['필수 조건','운전·차량·컴퓨터 활용 등 기관별 조건'],['우대 조건','사회복지사·요양보호사·관련 경력 여부']]),'생활지원사라는 같은 직무명이라도 운전면허와 차량을 필수로 보는 기관이 있고 우대로 두는 기관도 있습니다. 한 공고의 조건을 전국 공통 자격으로 설명하지 마세요.'],
['자격증보다 업무 적합성을 먼저 봅니다','일부 공고는 사회복지사나 요양보호사 자격을 우대하지만 필수 여부는 공고마다 다릅니다. 자격증이 없어도 지원 가능한 공고가 있을 수 있고, 자격증이 있어도 운전·이동·기록 업무가 맞지 않으면 근무가 어렵습니다.','대상자 가정을 방문하고 안부를 확인하는 과정에서 의사소통, 일정 관리와 기록이 중요합니다. 돌봄 경험을 과장하기보다 실제로 했던 지원과 경계를 지킨 사례를 준비하세요.'],
['급여와 근무시간은 함께 확인하세요','월급 숫자만 보면 전일제 일자리와 비교하기 어렵습니다. 주 소정근로시간, 교통비·통신비 등 별도 지급 여부, 휴게시간, 담당 인원과 추가근무 처리 방식을 확인합니다. 사업지침에 따른 급여라고 적혀 있다면 해당 연도 공고의 세부 내용을 봅니다.','기간제 계약이라면 계약 종료일, 다음 연도 사업 지속과 재채용 절차를 질문하세요. “정부 일자리”라는 표현이 무기계약이나 장기 고용을 보장하지 않습니다.'],
['지원서에는 공고의 실제 업무를 반영하세요','안부 확인, 외출 동행, 프로그램 지원, 생활정보 안내와 기록 중 자신의 경험과 연결되는 부분을 고릅니다. 가족 돌봄 경험은 도움이 될 수 있지만 공적 서비스에서 필요한 개인정보 보호와 업무 경계를 이해한다는 점도 중요합니다.','지원 전 기관 홈페이지의 지정 서식을 확인하고 제출 방식과 마감 시각을 지킵니다. 주민등록번호 등 요구하지 않은 민감정보를 이력서에 미리 적지 마세요.'],
['면접에서는 경계가 필요한 상황도 준비하세요','대상자가 금전 심부름이나 의료 판단처럼 업무 범위를 벗어난 부탁을 했을 때 어떻게 기관에 보고할지 생각해보세요. 친절하게 모든 부탁을 들어주는 것보다 안전과 개인정보 보호, 정해진 서비스 계획을 지키는 태도가 중요합니다.','혼자 판단하기 어려운 건강 변화, 학대 의심, 연락 두절과 위기 상황이 생겼을 때 보고 체계를 따르겠다는 점을 설명할 수 있어야 합니다. 실제 기관의 비상 연락 절차는 채용 후 교육에서 정확히 확인합니다.']
],[['요양보호사 자격증이 꼭 필요한가요?','공고마다 필수·우대 조건이 다릅니다. 특정 자격증을 전국 공통 필수로 단정하지 말고 실제 공고를 확인하세요.'],['생활지원사는 방문요양보호사와 같은 일인가요?','다릅니다. 노인맞춤돌봄서비스의 수행인력으로 기관의 서비스 계획에 따른 업무를 담당합니다.'],['자가용이 반드시 있어야 하나요?','담당 지역과 기관 공고에 따라 다릅니다. 운전면허·차량 소지·실제 운전 가능 여부를 구분해 확인하세요.']],
[['보건복지부 노인맞춤돌봄서비스 안내','https://www.mohw.go.kr/menu.es?mid=a10712010400'],['고용24 일자리 찾기','https://www.work24.go.kr/wk/a/b/1200/retriveDtlEmpSrchList.do']],['노인맞춤돌봄서비스-신청방법','돌봄-분야-재취업-가이드','중장년-재취업-이력서-작성법']),

post('에너지관리기능사-50대-취업-실기준비','에너지관리기능사 50대 취업 활용과 실기 준비 전 확인할 것','license','시설관리 자격 준비','energy-technician','시험 방식·작업형 실기·채용 연결','에너지관리기능사의 시험 구성과 작업형 실기 준비, 50대 시설관리 취업공고와 연결해 판단하는 방법을 정리했습니다.','에너지관리기능사는 보일러와 열설비를 다루는 국가기술자격입니다. 시설관리 취업에 도움이 될 수 있지만 자격증 이름만 보고 시작하기보다 실기 방식과 목표 공고를 함께 확인하세요.',[
['시험과 실제 일자리를 따로 보지 마세요','Q-Net은 에너지관리기능사의 필기를 열설비 설치·운전 및 관리, 실기를 열설비취급실무 작업형으로 안내합니다. 실기에는 적산과 배관작업 등이 포함되므로 필기 문제만 풀어 자격 전체를 준비하기 어렵습니다.','시설관리 공고에서 에너지관리기능사가 필수인지 우대인지, 실제 업무가 보일러 운전·점검과 관련되는지 확인하세요. 자격 취득이 선임 요건이나 채용을 자동으로 보장하지 않습니다.'],
['시작 전에 비용과 시간을 계산하세요',table('에너지관리기능사 준비표',[['필기','시험과목·출제기준·접수 회차 확인'],['실기','작업형 시간과 공개문제·도구 확인'],['연습','배관 작업 공간과 실제 연습시간'],['비용','수강료·재료·공구·응시료·이동비'],['취업 연결','희망 지역 공고의 필수·우대 조건']]),'국비지원 과정이라도 자비부담금과 재료비, 개인 공구가 별도일 수 있습니다. 과정 상세와 교육기관 설명을 대조하고 실제 실습 인원과 장비 사용시간을 질문하세요.'],
['작업형 실기는 손으로 확인해야 합니다','도면이나 작업 순서를 이해하는 것과 제한 시간 안에 안전하게 완성하는 것은 다릅니다. 공개문제와 출제기준을 바탕으로 측정, 절단, 나사 가공, 조립 등 교육과정의 실제 연습 범위를 확인하세요.','인터넷 영상은 흐름을 익히는 보조자료일 뿐 직접 작업과 안전지도를 대신하지 않습니다. 보호구와 공구는 공식 지참준비물 및 교육기관 안내를 기준으로 준비합니다.'],
['학원은 합격률보다 실습 조건을 비교하세요','상담할 때 전체 수업시간 중 개인 실습시간, 한 장비를 몇 명이 사용하는지, 보충 연습과 재료 제공 범위를 묻습니다. 합격률을 제시하면 집계 대상과 기간, 중도탈락자 포함 여부도 확인하세요.','통학시간과 생활패턴이 맞지 않으면 결석으로 실습량이 부족해질 수 있습니다. 직장인 과정은 야간·주말 일정과 시험 직전 연습 가능 여부를 함께 봅니다.'],
['시설관리 경로 안에서 우선순위를 정합니다','전기, 소방, 공조와 에너지 분야 자격을 모두 한 번에 준비할 필요는 없습니다. 희망 공고 10개에서 요구 빈도를 표시하고 현재 경력과 실습 부담을 비교하세요. 보일러·열설비 업무를 원하는지부터 분명히 하는 것이 좋습니다.','자격 취득 후에도 설비 운전 경험과 안전절차 이해가 필요합니다. 이력서에는 자격증 이름만 쓰기보다 실습에서 수행한 작업과 현장에서 더 배워야 할 부분을 사실대로 적으세요.'],
['접수 회차를 정한 뒤 역산해 준비하세요','필기 접수일, 시험일, 실기 접수와 시험기간을 달력에 표시하고 실제 연습 가능한 주를 계산합니다. 필기 합격 뒤 실기 학원을 찾기 시작하면 원하는 시간대가 없거나 연습기간이 부족할 수 있으므로 후보 교육기관은 미리 비교해두세요.','Q-Net 일정은 회차와 지역별 접수 가능 상황을 확인해야 합니다. 접수 시작일만 기억하지 말고 사진·결제수단·시험장 선택 등 원서접수 준비도 점검하며, 빈자리 접수만 기대해 전체 계획을 세우지 않는 편이 안전합니다.']
],[['에너지관리기능사는 필기만 합격하면 취득하나요?','아닙니다. 필기와 작업형 실기시험의 합격 기준을 모두 충족해야 합니다.'],['시설관리 취업에 반드시 필요한가요?','공고와 담당 설비에 따라 필수·우대 여부가 다릅니다. 희망 지역의 실제 채용공고를 먼저 비교하세요.'],['독학으로 실기 준비가 가능한가요?','작업형은 실제 도구와 안전한 연습환경이 필요합니다. 자신의 경험과 연습장소를 기준으로 교육 필요성을 판단하세요.']],
[['Q-Net 에너지관리기능사 종목정보','https://www.q-net.or.kr/crf005.do?id=crf00503&jmCd=7761'],['고용24 훈련과정 검색','https://www.work24.go.kr/hr/a/a/3100/selectTracseDetl.do']],['시설관리-자격증-조합','공조냉동기계기능사-4050-준비-전-확인할-것','큐넷-실기시험-준비물-조회방법'])
];
